-- Đồng bộ 13 bộ thẻ hệ thống: dọn 193 dòng trùng + sửa katakana/kana.
-- KHÔNG xoá rồi seed lại — giữ nguyên id thẻ để không mất tiến độ học.
-- Kiểm tra trước khi chạy:
--   SELECT COUNT(*) FROM flashcards WHERE id>=200000000;  -- phải = 18702

BEGIN;

-- ===== list 200000000  it_external/it_ha_tang_mang.json =====
--   giữ 1513, xoá 0, cập nhật 0
WITH s AS (SELECT id, ROW_NUMBER() OVER (ORDER BY flashcard_id) rn FROM flashcards_list_cards WHERE flashcards_list_id=200000000) UPDATE flashcards_list_cards l SET order_index=s.rn FROM s WHERE l.id=s.id;

