WITH s AS (SELECT id, ROW_NUMBER() OVER (ORDER BY flashcard_id) rn FROM flashcards_list_cards WHERE flashcards_list_id=200000012) UPDATE flashcards_list_cards l SET order_index=s.rn FROM s WHERE l.id=s.id;

-- Đồng bộ lại card_count theo số dòng thực tế
UPDATE flashcards_list l SET card_count = (SELECT COUNT(*) FROM flashcards_list_cards c WHERE c.flashcards_list_id = l.id) WHERE l.id >= 200000000;

